Bash(New-Item -Path "F:\AI-Development\physical-ai-textbook-New\physical-ai-textbook\site\src\css\buttons.module.css" -ItemType "file" -Value "// Button Styles for Physical AI & Humanoid Systems Landing Page

/* Primary Button */
.primaryButton {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75rem 1.5rem;
  font-size: 1rem;
  font-weight: var(--ifm-font-weight-semibold);
  line-height: 1.5;
  text-decoration: none !important; /* Override any link styles */
  border: 1px solid transparent;
  border-radius: 0.375rem; /* 6px */
  cursor: pointer;
  transition: all var(--ifm-transition-fast) ease;
  background-color: var(--ifm-color-primary);
  color: white;
  min-width: 120px;
}

.primaryButton:hover {
  background-color: var(--ifm-color-primary-dark);
  transform: translateY(-1px);
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

.primaryButton:focus {
  outline: 2px solid var(--ifm-color-primary-light);
  outline-offset: 2px;
}

.primaryButton:active {
  transform: translateY(0);
  box-shadow: 0 2px 4px -1px rgba(0, 0, 0, 0.1);
}

/* Secondary Button */
.secondaryButton {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.75rem 1.5rem;
  font-size: 1rem;
  font-weight: var(--ifm-font-weight-semibold);
  line-height: 1.5;
  text-decoration: none !important; /* Override any link styles */
  border: 1px solid var(--ifm-color-border);
  border-radius: 0.375rem; /* 6px */
  cursor: pointer;
  transition: all var(--ifm-transition-fast) ease;
  background-color: transparent;
  color: var(--ifm-color-content);
  min-width: 120px;
}

.secondaryButton:hover {
  background-color: color-mix(in srgb, var(--ifm-color-content) 10%, transparent);
  border-color: var(--ifm-color-primary);
  color: var(--ifm-color-primary);
}

.secondaryButton:focus {
  outline: 2px solid var(--ifm-color-primary-light);
  outline-offset: 2px;
}

.secondaryButton:active {
  transform: translateY(0);
  box-shadow: 0 2px 4px -1px rgba(0, 0, 0, 0.1);
}

/* Responsive adjustments */
@media (max-width: 996px) {
  .primaryButton,
  .secondaryButton {
    width: 100%;
    margin-bottom: 0.5rem;
  }
}")

